import { Controller } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { InventoryItem } from '../entities/inventoryItem.entity';

interface InventoryAdjustPayload {
  sku: string;
  delta: number;
  supplierId: string;
}

@Controller()
export class SupplyChainController {
  constructor(
    @InjectRepository(InventoryItem)
    private readonly itemRepo: Repository<InventoryItem>,
  ) {}

  @MessagePattern('supplier.inventory.adjust')
  async adjustStock(@Payload() data: InventoryAdjustPayload) {
    if (!data.supplierId) {
      return { success: false, reason: 'Supplier authentication missing', status: 401 };
    }

    // Verify that the inventory item belongs to the authorized supplier
    const item = await this.itemRepo.findOne({
      where: {
        sku: data.sku,
        supplierId: data.supplierId
      }
    });

    if (!item) {
      return { success: false, reason: 'SKU not found or not assigned to supplier', status: 403 };
    }

    item.stockQuantity += data.delta;
    await this.itemRepo.save(item);

    return { success: true, newStock: item.stockQuantity };
  }
}
